11	struct Node {
12	    i: u32, // original vertex index
13	    x: f64,
14	    y: f64,
15	    prev: u32,
16	    next: u32,
17	    z: i32, // 15-bit Morton code (0 until computed)
18	    prev_z: u32,
19	    next_z: u32,
