26	impl Index<u32> for Pool {
27	    type Output = Node;
28	    fn index(&self, id: u32) -> &Node {
29	        &self.0[id as usize]
30	    }
31	}
32	
33	impl IndexMut<u32> for Pool {
34	    fn index_mut(&mut self, id: u32) -> &mut Node {
35	        &mut self.0[id as usize]
36	    }
37	}
