39	pub fn earcut(points: &[[f64; 2]]) -> Vec<u32> {
40	    let m = points.len();
41	    let mut triangles: Vec<u32> = Vec::new();
42	    if m == 0 {
43	        return triangles;
44	    }
45	
46	    // Enable z-order hashing when flattened coordinate count > 160 (m > 80).
47	    let (hashing, min_x, min_y, inv_size) = if m * 2 > 160 {
48	        let mut min_x = points[0][0];
49	        let mut max_x = points[0][0];
50	        let mut min_y = points[0][1];
51	        let mut max_y = points[0][1];
52	        for p in &points[1..] {
53	            min_x = min_x.min(p[0]);
54	            max_x = max_x.max(p[0]);
55	            min_y = min_y.min(p[1]);
56	            max_y = max_y.max(p[1]);
57	        }
58	        let mut inv = (max_x - min_x).max(max_y - min_y);
59	        inv = if inv != 0.0 { 32767.0 / inv } else { 0.0 };
60	        (true, min_x, min_y, inv)
61	    } else {
62	        (false, 0.0, 0.0, 0.0)
63	    };
64	
65	    let mut e = Earcut {
66	        nodes: Pool(Vec::with_capacity(m)),
67	    };
68	    if let Some(outer) = e.linked_list(points, true) {
69	        if e.nodes[outer].prev == e.nodes[outer].next {
70	            return triangles;
71	        }
72	        e.earcut_linked(outer, &mut triangles, min_x, min_y, inv_size, 0, hashing);
73	    }
74	    triangles
75	}
