94	    // create a circular doubly linked list from the ring in source order when
95	    // clockwise == (signed area > 0), otherwise in reverse order
96	    fn linked_list(&mut self, points: &[[f64; 2]], clockwise: bool) -> Option<u32> {
97	        let m = points.len();
98	        if m == 0 {
99	            return None;
100	        }
101	        let mut last: Option<u32> = None;
102	        if clockwise == (Self::signed_area(points) > 0.0) {
103	            for i in 0..m {
104	                last = Some(self.insert_node(i as u32, points[i][0], points[i][1], last));
105	            }
106	        } else {
107	            for i in (0..m).rev() {
108	                last = Some(self.insert_node(i as u32, points[i][0], points[i][1], last));
109	            }
110	        }
111	        let mut last = last?;
112	        if self.nodes_eq(last, self.nodes[last].next) {
113	            self.remove_node(last);
114	            last = self.nodes[last].next;
115	        }
116	        Some(last)
