2	
3	use std::f64::consts::PI;
4	
5	/// Build the reference spiral of `2 * n` points.
6	///
7	/// For `i` in `0..2n`:
8	/// - `t = i as f64 / (2n) as f64`
9	/// - `radius = t`
10	/// - `angle = (4.0 * PI) * t`
11	/// - point = `(radius * cos(angle), radius * sin(angle))`
12	///
13	/// Negative or zero `n` yields an empty vector (no points).
14	pub fn spiral(n: i32) -> Vec<[f64; 2]> {
15	    if n <= 0 {
16	        return Vec::new();
17	    }
18	    let count = n * 2;
19	    let denom = count as f64;
20	    let mut points = Vec::with_capacity(count as usize);
21	    for i in 0..count {
22	        let t = i as f64 / denom;
23	        let radius = t;
24	        let angle = (4.0 * PI) * t;
25	        points.push([radius * angle.cos(), radius * angle.sin()]);
26	    }
27	    points
28	}
